/* #ifdef H5 */
import eruda from 'eruda'
/* #endif */

let inited = false
let replayTimer = null

/** Eruda 未就绪前的日志，就绪后再补打一次 */
const pendingLogs = []

function erudaOwnsConsole() {
  try {
    return /eruda/i.test(Function.prototype.toString.call(console.log))
  } catch (e) {
    return false
  }
}

function cloneLogPayload(payload) {
  try {
    return JSON.parse(JSON.stringify(payload))
  } catch (e) {
    return payload
  }
}

function replayPendingLogs() {
  if (!erudaOwnsConsole()) return false
  pendingLogs.forEach((entry) => {
    if (entry.replayed || entry.capturedAfterReady) return
    entry.replayed = true
    console.log(`${entry.label} [补打]`, entry.payload)
  })
  return true
}

function scheduleReplay() {
  if (replayTimer) return
  const startedAt = Date.now()
  replayTimer = setInterval(() => {
    const ready = replayPendingLogs()
    const drained = pendingLogs.every((entry) => entry.replayed || entry.capturedAfterReady)
    if ((ready && drained) || Date.now() - startedAt > 12000) {
      clearInterval(replayTimer)
      replayTimer = null
    }
  }, 200)
}

/** 立即打印，并缓存；Eruda 接管 console 后补打一次 */
export function cacheLog(label, payload) {
  pendingLogs.push({
    label,
    payload: cloneLogPayload(payload),
    replayed: false,
    capturedAfterReady: erudaOwnsConsole(),
  })
  console.log(label, payload)
  scheduleReplay()
}

/** 初始化 eruda 调试控制台（重复调用安全） */
export function initEruda() {
  /* #ifdef H5 */
  if (!inited) {
    eruda.init()
    inited = true
  }
  scheduleReplay()
  return true
  /* #endif */
  /* #ifndef H5 */
  return false
  /* #endif */
}

